package com.vandorlabs.client;

import com.google.gson.*;
import com.vandorlabs.network.MessageTokenSlot;
import com.vandorlabs.redstone.ChannelList;
import io.netty.buffer.*;
import java.nio.file.*;

/** Released MessageTokenSlot wire corpus; validity is the unchanged Handler scalar preflight. */
public final class StandaloneReaderEditorLegacyChecks {
    private static String hex(ByteBuf bytes){StringBuilder result=new StringBuilder();for(int i=bytes.readerIndex();i<bytes.writerIndex();i++)result.append(String.format("%02x",bytes.getUnsignedByte(i)));return result.toString();}
    public static void main(String[] args)throws Exception {
        net.minecraft.init.Bootstrap.register();net.minecraftforge.fml.common.registry.ForgeRegistries.ITEMS.register(com.vandorlabs.items.ModItems.REDSTONE_TRANSMITTER);
        JsonArray rows=new JsonArray();
        for(int mode:new int[]{0,1,2,3,4,255})for(int mask:new int[]{0,1,2,3,4,8,16,32,64,127,128})for(boolean any:new boolean[]{false,true})for(String channels:new String[]{"","27, 31","bad","1,"})for(int mount:new int[]{-1,0,27,63}){
            MessageTokenSlot original=new MessageTokenSlot(1947,mode,any,mask,channels).withMount(mount>=0,mount%4,mount/4%4,mount/16);
            ByteBuf wire=Unpooled.buffer();original.toBytes(wire);MessageTokenSlot decoded=new MessageTokenSlot();decoded.fromBytes(wire.duplicate());ByteBuf round=Unpooled.buffer();decoded.toBytes(round);
            if(!hex(wire).equals(hex(round)))throw new AssertionError("Released reader codec changed bytes");
            boolean valid=mode<=3&&(mask==0||mask==127||mask>=2&&mask<=64&&Integer.bitCount(mask)==1)&&channels.length()<=256&&ChannelList.parse(channels)!=null;
            JsonObject row=new JsonObject();row.addProperty("mode",mode);row.addProperty("any",any);row.addProperty("mask",mask);row.addProperty("channels",channels);row.addProperty("mount",mount);row.addProperty("wire",hex(wire));row.addProperty("valid",valid);rows.add(row);wire.release();round.release();
        }
        String serialized=rows.toString();java.security.MessageDigest digest=java.security.MessageDigest.getInstance("SHA-256");StringBuilder hash=new StringBuilder();for(byte b:digest.digest(serialized.getBytes("UTF-8")))hash.append(String.format("%02x",b&255));if(!hash.toString().equals("0c02d57ddba0456757e1c22aff3816f4367b2511abb0ad8a86172fb5690cf19f"))throw new AssertionError("Released reader editor wire changed "+hash);JsonObject root=new JsonObject();root.addProperty("golden",hash.toString());root.add("cases",rows);
        JsonArray transmissions=new JsonArray();for(int range:com.vandorlabs.redstone.TransmissionSettings.RANGES)for(boolean local:new boolean[]{false,true})for(int count:new int[]{0,1,2,64}){
            int[] values=new int[count];for(int i=0;i<count;i++)values[i]=1000000000+i;ChannelList channels=ChannelList.of(values);ByteBuf wire=Unpooled.buffer();com.vandorlabs.network.MessageTransmitterSlot.settings(1947,0,channels,range,local).toBytes(wire);
            com.vandorlabs.network.MessageTransmitterSlot decoded=new com.vandorlabs.network.MessageTransmitterSlot();decoded.fromBytes(wire.duplicate());ByteBuf round=Unpooled.buffer();decoded.toBytes(round);if(!hex(wire).equals(hex(round)))throw new AssertionError("Source transmitter round trip");JsonObject row=new JsonObject();row.addProperty("range",range);row.addProperty("local",local);row.addProperty("channels",channels.toString());row.addProperty("bytes",wire.readableBytes());row.addProperty("wire",hex(wire));transmissions.add(row);wire.release();round.release();
        }
        root.add("transmissions",transmissions);StringBuilder transmissionHash=new StringBuilder();for(byte b:digest.digest(transmissions.toString().getBytes("UTF-8")))transmissionHash.append(String.format("%02x",b&255));if(!transmissionHash.toString().equals("38c0a1bc782188537156caefadd086eb486299ff4dc24a1c9e6f36415505484d"))throw new AssertionError("Released reader transmission wire changed "+transmissionHash);root.addProperty("transmissionGolden",transmissionHash.toString());
        JsonArray loads=new JsonArray();for(int module=0;module<4;module++)for(int scalar:new int[]{-3,0,27,Integer.MAX_VALUE})for(int array=0;array<7;array++){
            net.minecraft.nbt.NBTTagCompound raw=new net.minecraft.nbt.NBTTagCompound();raw.setInteger("RedstoneChannel",scalar);raw.setString("FutureReader","retained");if(array==1)raw.setString("RedstoneChannels","wrong type");if(array>=2){int[] values=array==2?new int[0]:array==3?new int[]{31,27}:array==4?new int[]{-1,27}:array==5?new int[]{27,27}:java.util.stream.IntStream.rangeClosed(1,65).toArray();raw.setIntArray("RedstoneChannels",values);}
            if(module>0){net.minecraft.nbt.NBTTagCompound item=new net.minecraft.nbt.NBTTagCompound();item.setString("id",module==2?"missing:transmitter":"vandorlabs:redstone_transmitter");item.setByte("Count",(byte)1);item.setShort("Damage",(short)0);net.minecraft.nbt.NBTTagCompound tag=new net.minecraft.nbt.NBTTagCompound();tag.setIntArray("RedstoneChannels",new int[]{41,43});item.setTag("tag",tag);if(module==3){net.minecraft.nbt.NBTTagCompound caps=new net.minecraft.nbt.NBTTagCompound();caps.setString("missing:ownership","keep");item.setTag("ForgeCaps",caps);}net.minecraft.nbt.NBTTagCompound modules=new net.minecraft.nbt.NBTTagCompound();modules.setTag("main",item);net.minecraft.nbt.NBTTagCompound forge=new net.minecraft.nbt.NBTTagCompound();forge.setTag("VandorTransmitters",modules);raw.setTag("ForgeData",forge);}
            String original=raw.toString();com.vandorlabs.tiles.TileEntityTokenSlot tile=new com.vandorlabs.tiles.TileEntityTokenSlot(false);tile.readFromNBT(raw);if(!original.equals(raw.toString()))throw new AssertionError("Released reader load mutates input");JsonObject row=new JsonObject();row.addProperty("input",original);row.addProperty("ownershipSafe",module<2);row.addProperty("channels",tile.getRedstoneChannels().toString());row.addProperty("transmission",com.vandorlabs.redstone.TransmitterSlots.channels(tile).toString());row.addProperty("range",com.vandorlabs.redstone.TransmitterSlots.range(tile));row.addProperty("local",com.vandorlabs.redstone.TransmitterSlots.localRedstone(tile));row.addProperty("data",tile.getTileData().toString());loads.add(row);
        }
        StringBuilder loadHash=new StringBuilder();for(byte b:digest.digest(loads.toString().getBytes("UTF-8")))loadHash.append(String.format("%02x",b&255));if(!loadHash.toString().equals("7ddbe6b8575091e94c1e1a88b39a0028e22adad73845dc205b01660bdee86687"))throw new AssertionError("Released reader channel load changed "+loadHash);root.add("loads",loads);root.addProperty("loadGolden",loadHash.toString());Path output=Paths.get(System.getProperty("vandorlabs.standaloneReaderEditorReference","build/test-artifacts/standalone-reader-editor-forge.json"));Files.createDirectories(output.toAbsolutePath().getParent());try(java.io.Writer writer=Files.newBufferedWriter(output)){new Gson().toJson(root,writer);}System.out.println("Actual standalone reader editor wire PASS cases="+rows.size()+" golden="+hash+" transmissions="+transmissions.size()+" transmissionGolden="+transmissionHash+" loads="+loads.size()+" loadGolden="+loadHash);
    }
}
